#pragma once

#include "constants.hpp"
#include "filesystem_utility.hpp"
#include "logger.hpp"
#include "process_lifecycle_manager.hpp"
#include "types/core_service_permission_check_result.hpp"
#include <IOKit/hidsystem/IOHIDLib.h>
#include <fstream>
#include <mutex>
#include <nlohmann/json.hpp>
#include <nod/nod.hpp>
#include <optional>
#include <pqrs/dispatcher.hpp>
#include <pqrs/osx/accessibility.hpp>
#include <pqrs/osx/workspace.hpp>
#include <thread>

namespace krbn::core_service::agent {

class permission_checker final : public pqrs::dispatcher::extra::dispatcher_client {
public:
  nod::signal<void(const core_service_permission_check_result&)> permission_check_result_changed;

  permission_checker(const permission_checker&) = delete;

  permission_checker()
      : dispatcher_client(),
        check_permissions_task_(*this) {
  }

  ~permission_checker() override {
    detach_from_dispatcher();
  }

  void async_set_on_console(std::optional<bool> value) {
    enqueue_to_dispatcher([this, value] {
      on_console_ = value;
      check_permissions();
    });
  }

  void enqueue_check_permissions(std::chrono::milliseconds delay = std::chrono::milliseconds(0)) {
    check_permissions_task_.debounce_after(
        [this] {
          check_permissions();
        },
        delay);
  }

private:
  void check_permissions() {
    if (on_console_ != std::optional<bool>(true)) {
      return;
    }

    // `make_bundle_permission_check_result` blocks while waiting for the permission-check result file.
    // This is acceptable here because this path is only relevant while the required permissions are not granted,
    // and during that period the agent has little else to do besides prompting for and re-checking permissions.
    auto result = make_bundle_permission_check_result();
    if (!result) {
      enqueue_check_permissions(std::chrono::seconds(1));
      return;
    }

    // On macOS 26, Accessibility permission may also cover Input Monitoring permission.
    // (Note that on macOS 14, Input Monitoring permission is still required separately even if Accessibility is granted.)
    // Therefore, request Accessibility permission first, and only request Input Monitoring permission
    // if it is still needed after Accessibility has already been granted.
    if (!result->get_accessibility_process_trusted()) {
      prompt_accessibility_permission_once();
    } else {
      if (!result->get_iohid_listen_event_allowed()) {
        prompt_input_monitoring_permission_once();
      }
    }

    // If permissions were revoked while the agent kept running, the cached bundle permission state can become stale.
    // In that case, terminate the agent and let launchd restart the agent.
    // The restarted process can re-enter the normal prompt-and-poll flow from a clean state.
    if (last_bundle_permission_check_result_ &&
        last_bundle_permission_check_result_->required_permissions_granted() &&
        !result->required_permissions_granted()) {
      logger::get_logger()->info("Required permissions were revoked. Terminating the agent.");

      last_bundle_permission_check_result_ = *result;

      process_lifecycle_manager::async_request_termination();
      return;
    }

    if (!result->required_permissions_granted()) {
      restart_required_after_permissions_granted_ = true;
      enqueue_check_permissions(std::chrono::seconds(1));
    }

    last_bundle_permission_check_result_ = *result;
    permission_check_result_changed(*result);

    if (!result->required_permissions_granted()) {
      return;
    }

    if (restart_required_after_permissions_granted_) {
      logger::get_logger()->info("The required permissions are granted. Restarting core daemons and terminating the agent.");

      process_lifecycle_manager::async_request_termination();
    }
  }

  static constexpr const char* karabiner_core_service_bundle_path = "/Library/Application Support/org.pqrs/Karabiner-Elements/Karabiner-Core-Service.app";

  static std::optional<core_service_permission_check_result> make_bundle_permission_check_result() {
    filesystem_utility::prepare_user_directories();

    auto result_json_file_path =
        constants::get_user_tmp_directory() / "core-service-permission-check-result.json";
    filesystem_utility::remove(result_json_file_path);

    pqrs::osx::workspace::open_application_by_bundle_path(
        karabiner_core_service_bundle_path,
        pqrs::osx::workspace::open_configuration{
            .activates = false,
            .adds_to_recent_items = false,
            .creates_new_application_instance = true,
            .arguments = {
                "permission-check",
                result_json_file_path.string(),
            }});

    for (int i = 0; i < 50; ++i) {
      std::this_thread::sleep_for(std::chrono::milliseconds(100));

      if (!filesystem_utility::exists(result_json_file_path)) {
        continue;
      }

      try {
        std::ifstream input(result_json_file_path);
        auto json = nlohmann::json::parse(input);
        return json.get<core_service_permission_check_result>();
      } catch (const std::exception& e) {
        logger::get_logger()->error("failed to read permission check result: {0}", e.what());
        break;
      }
    }

    return std::nullopt;
  }

  static void prompt_accessibility_permission_once() {
    static std::once_flag once;

    std::call_once(once, [] {
      pqrs::osx::accessibility::is_process_trusted_with_prompt();
    });
  }

  static void prompt_input_monitoring_permission_once() {
    static std::once_flag once;

    std::call_once(once, [] {
      IOHIDRequestAccess(kIOHIDRequestTypeListenEvent);
    });
  }

  std::optional<bool> on_console_;
  std::optional<core_service_permission_check_result> last_bundle_permission_check_result_;
  bool restart_required_after_permissions_granted_ = false;
  pqrs::dispatcher::extra::debounced_task check_permissions_task_;
};

} // namespace krbn::core_service::agent

#pragma once

#include "core_configuration/core_configuration.hpp"
#include "device_properties.hpp"
#include "device_utility.hpp"
#include "event_queue.hpp"
#include "game_pad_stick_converter.hpp"
#include "hid_device_events_monitor.hpp"
#include "hid_keyboard_caps_lock_led_state_manager.hpp"
#include "iokit_utility.hpp"
#include "pressed_keys_manager.hpp"
#include "run_loop_thread_utility.hpp"
#include "types.hpp"

namespace krbn::core_service::daemon::device_grabber_details {
class entry final : public pqrs::dispatcher::extra::dispatcher_client {
public:
  //
  // Signals (invoked from the shared dispatcher thread)
  //

  nod::signal<void(entry&,
                   event_queue::not_null_entries_ptr_t event_queue_entries)>
      hid_values_arrived;

  //
  // Methods
  //

  entry(const entry&) = delete;

  entry(device_id device_id,
        IOHIDDeviceRef device,
        pqrs::not_null_shared_ptr_t<const core_configuration::core_configuration> core_configuration)
      : dispatcher_client(),
        device_id_(device_id),
        core_configuration_(core_configuration),
        device_properties_(device_properties::make_device_properties(device_id,
                                                                     device)),
        pressed_keys_manager_(std::make_shared<pressed_keys_manager>()),
        disabled_(false),
        temporarily_ignore_(false) {
    caps_lock_led_state_manager_ = std::make_shared<krbn::hid_keyboard_caps_lock_led_state_manager>(device);

    hid_device_events_monitor_ = std::make_shared<hid_device_events_monitor>(
        pqrs::dispatcher::extra::get_shared_dispatcher(),
        pqrs::cf::run_loop_thread::extra::get_shared_run_loop_thread(),
        device,
        *device_properties_,
        hid_device_events_monitor::configuration{
            .enable_input_report_handler = true,
        });
    hid_device_events_monitor_->started.connect([this] {
      control_caps_lock_led_state_manager();

      if (seized()) {
        if (device_properties_->get_device_identifiers().get_is_game_pad()) {
          game_pad_stick_converter_ = std::make_unique<game_pad_stick_converter>(device_properties_,
                                                                                 core_configuration_);
          game_pad_stick_converter_->pointing_motion_arrived.connect([this](auto&& event_queue_entry) {
            auto event_queue_entries = std::make_shared<std::vector<event_queue::not_null_const_entry_ptr_t>>();
            event_queue_entries->push_back(event_queue_entry);

            hid_values_arrived(*this,
                               event_queue_entries);
          });
        }
      }
    });
    hid_device_events_monitor_->stopped.connect([this] {
      control_caps_lock_led_state_manager();

      game_pad_stick_converter_ = nullptr;
    });
    hid_device_events_monitor_->values_arrived.connect([this](auto&& values_ptr) {
      auto d = core_configuration_->get_selected_profile().get_device(device_properties_->get_device_identifiers());

      auto hid_values = *values_ptr;

      //
      // Eliminated the entries that needed to be removed from hid_values
      //

      std::erase_if(hid_values,
                    [this, &d](const auto& v) {
                      //
                      // Handle ignore_vendor_events
                      //

                      // For Apple devices, process vendor events regardless of the "ignore_vendor_events" setting.
                      // Even if karabiner.json is manually edited to set "ignore_vendor_events": true,
                      // ignore that setting and handle vendor events.
                      if (d->get_ignore_vendor_events() &&
                          !device_properties_->get_is_apple()) {
                        // 0xff
                        if (v.get_usage_page() == pqrs::hid::usage_page::apple_vendor_top_case) {
                          return true;
                        }

                        // Vendor-defined (0xff00-0xffff)
                        if (v.get_usage_page() >= pqrs::hid::usage_page::value_t(0xff00) &&
                            v.get_usage_page() <= pqrs::hid::usage_page::value_t(0xffff)) {
                          return true;
                        }
                      }

                      //
                      // Filter useless events
                      //

                      if (core_configuration_->get_global_configuration().get_filter_useless_events_from_specific_devices()) {
                        if (device_properties_->get_device_identifiers().is_nintendo_pro_controller_0x057e_0x2009() &&
                            device_properties_->get_transport() == "USB") {
                          // Nintendo's Pro Controller, when connected via USB, generates a high frequency of events even when no input is made.
                          // As these events contain no meaningful information, they should be ignored.

                          // Since button on/off events keep firing endlessly, they must be ignored.
                          if (v.get_usage_page() == pqrs::hid::usage_page::button) {
                            return true;
                          }

                          // The sticks continuously move randomly, they must be ignored.
                          if (v.get_usage_page() == pqrs::hid::usage_page::generic_desktop &&
                              (v.get_usage() == pqrs::hid::usage::generic_desktop::x ||
                               v.get_usage() == pqrs::hid::usage::generic_desktop::y ||
                               v.get_usage() == pqrs::hid::usage::generic_desktop::z ||
                               v.get_usage() == pqrs::hid::usage::generic_desktop::rz)) {
                            return true;
                          }
                        }
                      }

                      return false;
                    });

      //
      // Make event queue
      //

      auto event_queue_entries = event_queue::utility::make_entries(device_properties_,
                                                                    hid_values,
                                                                    {
                                                                        .pointing_motion_xy_multiplier = d->get_pointing_motion_xy_multiplier(),
                                                                        .pointing_motion_wheels_multiplier = d->get_pointing_motion_wheels_multiplier(),
                                                                    });

      event_queue_entries = event_queue::utility::insert_device_keys_and_pointing_buttons_are_released_event(event_queue_entries,
                                                                                                             device_id_,
                                                                                                             pressed_keys_manager_);
      hid_values_arrived(*this,
                         event_queue_entries);

      //
      // game pad stick to pointing motion
      //

      if (game_pad_stick_converter_) {
        game_pad_stick_converter_->convert(hid_values);
      }
    });

    device_name_ = iokit_utility::make_device_name_for_log(device_id,
                                                           device);
    device_short_name_ = iokit_utility::make_device_name(device);
  }

  ~entry() {
    detach_from_dispatcher([this] {
      hid_device_events_monitor_ = nullptr;
      game_pad_stick_converter_ = nullptr;
      caps_lock_led_state_manager_ = nullptr;
    });
  }

  [[nodiscard]] device_id get_device_id() const {
    return device_id_;
  }

  // This method should be called in the shared dispatcher thread.
  void set_core_configuration(pqrs::not_null_shared_ptr_t<const core_configuration::core_configuration> core_configuration) {
    core_configuration_ = core_configuration;

    control_caps_lock_led_state_manager();

    if (game_pad_stick_converter_) {
      game_pad_stick_converter_->set_core_configuration(core_configuration);
    }
  }

  [[nodiscard]] pqrs::not_null_shared_ptr_t<device_properties> get_device_properties() const {
    return device_properties_;
  }

  [[nodiscard]] pqrs::not_null_shared_ptr_t<pressed_keys_manager> get_pressed_keys_manager() const {
    return pressed_keys_manager_;
  }

  [[nodiscard]] std::shared_ptr<hid_device_events_monitor> get_hid_device_events_monitor() const {
    return hid_device_events_monitor_;
  }

  void set_caps_lock_led_state(std::optional<led_state> state) {
    caps_lock_led_state_manager_->set_state(state);
  }

  [[nodiscard]] const std::string& get_device_name() const {
    return device_name_;
  }

  [[nodiscard]] const std::string& get_device_short_name() const {
    return device_short_name_;
  }

  [[nodiscard]] bool get_disabled() const {
    return disabled_;
  }

  void set_disabled(bool value) {
    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      return;
    }

    disabled_ = value;
  }

  [[nodiscard]] bool get_temporarily_ignore() const {
    return temporarily_ignore_;
  }

  void set_temporarily_ignore(bool value) {
    temporarily_ignore_ = value;
  }

  [[nodiscard]] bool is_disable_built_in_keyboard_if_exists() const {
    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      return false;
    }

    if (device_properties_->get_is_built_in_keyboard() ||
        device_properties_->get_is_built_in_pointing_device() ||
        device_properties_->get_is_built_in_touch_bar()) {
      return false;
    }

    auto d = core_configuration_->get_selected_profile().get_device(device_properties_->get_device_identifiers());
    return d->get_disable_built_in_keyboard_if_exists();
  }

  [[nodiscard]] bool determine_is_built_in_keyboard() const {
    return device_utility::determine_is_built_in_keyboard(*core_configuration_, *device_properties_);
  }

  void async_start_hid_device_events_monitor(grabbable_state::state state) {
    auto options = kIOHIDOptionsTypeNone;

    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      options = kIOHIDOptionsTypeNone;
    } else {
      switch (state) {
        case grabbable_state::state::grabbable:
          if (needs_to_seize_device()) {
            options = kIOHIDOptionsTypeSeizeDevice;
          }
          break;

        case grabbable_state::state::ungrabbable:
        case grabbable_state::state::none:
        case grabbable_state::state::end_:
          // Do not start hid_device_events_monitor_.
          return;
      }
    }

    //
    // Start
    //

    hid_device_events_monitor_->async_start(options,
                                            std::chrono::milliseconds(1000));
  }

  void async_stop_hid_device_events_monitor() {
    hid_device_events_monitor_->async_stop();
  }

  [[nodiscard]] bool seized() const {
    return hid_device_events_monitor_->seized();
  }

  [[nodiscard]] bool needs_to_observe_device() const {
    // We must monitor the {pqrs::hid::usage_page::leds, pqrs::hid::usage::led::caps_lock} event from the virtual HID keyboard to manage the caps lock LED on physical keyboards.
    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      return true;
    }

    return false;
  }

  // Return whether the device is a target for modifying input events.
  [[nodiscard]] bool needs_to_seize_device() const {
    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      return false;
    }

    if (temporarily_ignore_) {
      return false;
    }

    // We have to seize the device in order to discard all input events.
    if (disabled_) {
      return true;
    }

    return !device_utility::determine_should_ignore_device(*core_configuration_,
                                                           *device_properties_);
  }

private:
  void control_caps_lock_led_state_manager() {
    if (device_properties_->get_device_identifiers().get_is_virtual_device()) {
      return;
    }

    if (caps_lock_led_state_manager_) {
      auto d = core_configuration_->get_selected_profile().get_device(device_properties_->get_device_identifiers());
      if (d->get_manipulate_caps_lock_led()) {
        if (seized()) {
          caps_lock_led_state_manager_->async_start();
          return;
        }
      }

      caps_lock_led_state_manager_->async_stop();
    }
  }

  device_id device_id_;
  pqrs::not_null_shared_ptr_t<const core_configuration::core_configuration> core_configuration_;
  pqrs::not_null_shared_ptr_t<device_properties> device_properties_;
  pqrs::not_null_shared_ptr_t<pressed_keys_manager> pressed_keys_manager_;
  std::shared_ptr<hid_keyboard_caps_lock_led_state_manager> caps_lock_led_state_manager_;
  std::shared_ptr<hid_device_events_monitor> hid_device_events_monitor_;
  std::unique_ptr<game_pad_stick_converter> game_pad_stick_converter_;
  std::string device_name_;
  std::string device_short_name_;

  // For disabling the built in keyboard
  bool disabled_;

  // For ignoring all devices via EventViewer
  bool temporarily_ignore_;
};
} // namespace krbn::core_service::daemon::device_grabber_details

#pragma once

#include "core_service/agent/components_manager.hpp"
#include "core_service/core_service_utility.hpp"
#include "environment_variable_utility.hpp"
#include "filesystem_utility.hpp"
#include "karabiner_version.h"
#include "logger.hpp"
#include "process_lifecycle_manager.hpp"
#include "services_utility.hpp"
#include <IOKit/hidsystem/IOHIDLib.h>
#include <fstream>
#include <iostream>
#include <nlohmann/json.hpp>
#include <pqrs/osx/accessibility.hpp>
#include <pqrs/osx/application.hpp>

namespace krbn::core_service::main {
int agent(std::vector<std::string> args) {
  auto log_cli_error = [](const std::string& message) {
    if (!constants::get_user_log_directory().empty()) {
      logger::set_async_rotating_logger("core_service (cli)",
                                        constants::get_user_log_directory() / "core_service_cli.log",
                                        pqrs::spdlog::filesystem::log_directory_perms_0700);
    }
    logger::get_logger()->error(message);
    std::cerr << message << std::endl;
  };

  //
  // Call NSApplication.shared.finishLaunching() in order to avoid the following error
  // when the app is launched by the open command or similar methods.
  // This is especially problematic when it is executed with the permission-check argument.
  //
  // _LSOpenURLsWithCompletionHandler() failed for the application Karabiner-Core-Service.app with error -1712.
  //

  pqrs::osx::application::finish_launching();

  //
  // Process arguments
  //

  for (std::size_t i = 1; i < args.size(); ++i) {
    if (args[i] == "permission-check") {
      if (i + 1 >= args.size()) {
        log_cli_error("missing result path");
        return 1;
      }

      auto result = core_service::core_service_utility::make_current_process_permission_check_result();
      auto result_json_file_path = std::filesystem::path(args[i + 1]);
      auto temporary_result_json_file_path = result_json_file_path;
      temporary_result_json_file_path += ".tmp";

      try {
        std::ofstream output(temporary_result_json_file_path);
        output << nlohmann::json(result).dump();
        output.close();

        if (!filesystem_utility::rename(temporary_result_json_file_path,
                                        result_json_file_path)) {
          return 1;
        }

        return 0;
      } catch (const std::exception& e) {
        log_cli_error(e.what());
        return 1;
      }

    } else {
      log_cli_error("unsupported argument: " + args[i]);
      return 1;
    }
  }

  //
  // Load custom environment variables
  //

  auto environment_variables = environment_variable_utility::load_custom_environment_variables();

  //
  // Setup logger
  //

  if (!constants::get_user_log_directory().empty()) {
    logger::set_async_rotating_logger("core_service (agent)",
                                      constants::get_user_log_directory() / "core_service.log",
                                      pqrs::spdlog::filesystem::log_directory_perms_0700);
  }

  logger::get_logger()->info("version {0}", karabiner_version);

  //
  // Log custom environment variables
  //

  environment_variable_utility::log(environment_variables);

  //
  // Get codesign
  //

  get_shared_codesign_manager()->log();

  //
  // If the Karabiner-Console-User-Server LaunchAgent plist is renamed in an update,
  // the agent will not start automatically until it is registered again.
  //

  services_utility::register_core_agents();

  //
  // The agent opens karabiner.json to trigger the disk-access permission prompt,
  // in case ~/.config/karabiner is a symlink and karabiner.json lives under Documents or similar.
  //

  std::ifstream input(constants::get_user_core_configuration_file_path());

  //
  // Run process_lifecycle_manager
  //

  process_lifecycle_manager::initialize_shared_instance(
      process_lifecycle_manager::configuration{
          .components_manager_maker =
              [] {
                return std::make_unique<core_service::agent::components_manager>();
              },
          .termination_completion_handler =
              [] {
                dispatch_async(dispatch_get_main_queue(), ^{
                  pqrs::osx::application::stop();
                });
              },
      });

  // This is needed because this agent uses pqrs::osx::application::run.
  // AppKit termination requests should go through process_lifecycle_manager so
  // components and the power management monitor are destroyed before the AppKit run loop stops.
  pqrs::osx::application::set_should_terminate_callback([] {
    if (process_lifecycle_manager::async_request_termination()) {
      return pqrs::osx::application::terminate_reply::cancel;
    }

    return pqrs::osx::application::terminate_reply::now;
  });

  process_lifecycle_manager::async_start();

  // Use the AppKit application run loop because the agent uses
  // pqrs::osx::accessibility::monitor and other AppKit/main-thread APIs.
  pqrs::osx::application::run();

  process_lifecycle_manager::terminate_shared_instance();

  return 0;
}
} // namespace krbn::core_service::main

#pragma once

#include "app_icon.hpp"
#include "codesign_manager.hpp"
#include "constants.hpp"
#include "core_service/core_service_utility.hpp"
#include "core_service/daemon/components_manager.hpp"
#include "core_service/daemon/core_service_daemon_state_manager.hpp"
#include "filesystem_utility.hpp"
#include "karabiner_version.h"
#include "logger.hpp"
#include "process_lifecycle_manager.hpp"
#include "services_utility.hpp"
#include "termination_signal_monitor.hpp"
#include <iostream>
#include <mach/mach.h>
#include <pqrs/osx/workspace.hpp>

namespace krbn::core_service::main {

int daemon() {
  // Note:
  // Processes running as root should not rely on environment variables,
  // so we do not load custom environment variables in the core_service daemon.

  //
  // Setup logger
  //

  logger::set_async_rotating_logger("core_service (daemon)",
                                    "/var/log/karabiner/core_service.log",
                                    pqrs::spdlog::filesystem::log_directory_perms_0755);
  logger::get_logger()->info("version {0}", karabiner_version);

  //
  // Get codesign
  //

  get_shared_codesign_manager()->log();

  //
  // Run repair.sh
  //

  system("/bin/bash '/Library/Application Support/org.pqrs/Karabiner-Elements/repair.sh'");

  //
  // Check Karabiner-Elements.app exists
  //

  auto settings_application_url = pqrs::osx::workspace::find_application_url_by_bundle_identifier("org.pqrs.Karabiner-Elements.Settings");
  logger::get_logger()->info("Karabiner-Elements.app path: {0}", settings_application_url);

  //
  // Prepare core_service_daemon_state_manager
  //

  auto core_service_daemon_state_manager = std::make_shared<daemon::core_service_daemon_state_manager>();
  {
    auto permission_check_result = core_service_utility::make_current_process_permission_check_result();
    core_service_daemon_state_manager->set_current_process_permission_check_result(permission_check_result);
    // Immediately after startup, current_process_permission_check_result and bundle_permission_check_result are the same, so set both.
    core_service_daemon_state_manager->set_bundle_permission_check_result(permission_check_result);
  }

  //
  // Set task_qos_policy
  //

  {
    task_qos_policy qosinfo;

    memset(&qosinfo, 0, sizeof(qosinfo));
    qosinfo.task_latency_qos_tier = LATENCY_QOS_TIER_0;
    qosinfo.task_throughput_qos_tier = THROUGHPUT_QOS_TIER_0;
    pqrs::osx::kern_return kr = task_policy_set(mach_task_self(),
                                                TASK_BASE_QOS_POLICY,
                                                reinterpret_cast<task_policy_t>(&qosinfo),
                                                TASK_QOS_POLICY_COUNT);
    if (kr) {
      logger::get_logger()->debug("task_policy_set is called.");
    } else {
      logger::get_logger()->warn("task_policy_set error: {0}", kr);
    }
  }

  //
  // Make directories.
  //

  filesystem_utility::prepare_system_directories(std::nullopt);

  //
  // Run process_lifecycle_manager
  //

  auto weak_core_service_daemon_state_manager = std::weak_ptr<daemon::core_service_daemon_state_manager>(core_service_daemon_state_manager);
  process_lifecycle_manager::initialize_shared_instance(
      process_lifecycle_manager::configuration{
          .components_manager_maker =
              [weak_core_service_daemon_state_manager] {
                return std::make_unique<daemon::components_manager>(weak_core_service_daemon_state_manager);
              },
          .termination_completion_handler =
              [] {
                dispatch_async(dispatch_get_main_queue(), ^{
                  CFRunLoopStop(CFRunLoopGetCurrent());
                });
              },
          // Give device_grabber time to release seized devices asynchronously
          // before acknowledging the system sleep notification.
          .system_will_sleep_delay = std::chrono::seconds(3),
      });

  termination_signal_monitor signal_monitor([](int) {
    process_lifecycle_manager::async_request_termination();
  });

  process_lifecycle_manager::async_start();

  CFRunLoopRun();

  process_lifecycle_manager::terminate_shared_instance();

  //
  // Cleanup
  //

  core_service_daemon_state_manager = nullptr;

  logger::get_logger()->info("Karabiner-Core-Service is terminated.");

  return 0;
}
} // namespace krbn::core_service::main

